"""Optional authorized public earnings-event import, never generated by AI.

No live consensus source is assumed. The existing read-only public filing
mount can carry a separately reviewed, licensed normalized event feed.
Operator attestations are not independent verification by ATLAS. No secrets,
raw filings, URLs, or source text are forwarded into an AI prompt.
"""
import json,os,re,stat
from pathlib import Path
from datetime import date,datetime
from urllib.parse import urlsplit
from .replay_evidence import exact_isin
from .professional_strategies import pead
PATH=Path("/app/filing-reports/earnings-expectations.json")
LIMIT=2_000_000

def permitted():
    return os.getenv("ATLAS_EARNINGS_EXPECTATIONS_ENABLED","false").lower()=="true" and os.getenv("MARKET_DATA_USAGE_RIGHTS_CONFIRMED","false").lower()=="true"

def source(v):
    if not isinstance(v,str) or len(v)>500 or re.search(r"[\s\\]",v):return False
    try:
        u=urlsplit(v)
        return u.scheme=="https" and bool(u.hostname) and not u.username and not u.password and u.port in (None,443) and bool(u.path) and not u.query and not u.fragment
    except ValueError:return False

def normalize(payload,instant):
    if not isinstance(payload,dict) or payload.get("methodology")!="AUTHORIZED-EARNINGS-EVENTS-1":return {}
    events=payload.get("events")
    if not isinstance(events,list) or len(events)>5000:return {}
    result={};conflicts=set()
    for e in events:
        if not isinstance(e,dict) or not exact_isin(e.get("isin")) or e.get("operator_reviewed") is not True:continue
        if not all(source(e.get(k)) for k in ("consensus_source","release_source")):continue
        if urlsplit(e["consensus_source"]).hostname==urlsplit(e["release_source"]).hostname:continue
        if not all(isinstance(e.get(k),str) and re.fullmatch(r"[0-9a-f]{64}",e[k]) for k in ("consensus_document_sha256","release_document_sha256")):continue
        if e["consensus_document_sha256"]==e["release_document_sha256"]:continue
        try:
            period=date.fromisoformat(e["quarter_end"])
            release=datetime.fromisoformat(e["released_at"])
            if not period<release.date() or (release.date()-period).days>150 or pead(e,instant) is None:continue
        except (ValueError,TypeError,KeyError):continue
        isin=e["isin"]
        public={k:e[k] for k in ("isin","quarter_end","consensus_eps","actual_eps","consensus_as_of","released_at","consensus_verified","release_verified","same_share_basis","analyst_count")}
        if isin in result and result[isin]!=public:conflicts.add(isin)
        result[isin]=public
    return {k:v for k,v in result.items() if k not in conflicts}

def read(instant,path=PATH):
    if not permitted():return {}
    try:
        fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
        with os.fdopen(fd,"rb") as f:
            info=os.fstat(f.fileno())
            if not stat.S_ISREG(info.st_mode) or info.st_size>LIMIT:return {}
            raw=f.read(LIMIT+1)
        if len(raw)>LIMIT:return {}
        return normalize(json.loads(raw),instant)
    except (OSError,ValueError,TypeError,OverflowError):return {}
